package com.shoply.infrastructure.persistence;
import com.shoply.domain.model.User; import com.shoply.domain.repository.UserRepository; import com.shoply.infrastructure.persistence.entity.UserEntity; import com.shoply.infrastructure.persistence.repository.SpringDataUserRepository; import java.util.Optional; import org.springframework.stereotype.Repository;
@Repository public class UserPersistenceAdapter implements UserRepository {private final SpringDataUserRepository users;public UserPersistenceAdapter(SpringDataUserRepository users){this.users=users;}public Optional<User> findByEmail(String email){return users.findByEmail(email).map(e->new User(e.getId(),e.getEmail(),e.getPasswordHash(),"CUSTOMER"));}public User save(User user){var e=users.save(new UserEntity(user.id(),user.email(),user.passwordHash()));return new User(e.getId(),e.getEmail(),e.getPasswordHash(),"CUSTOMER");}}
